/**
 * Settings -> Abilities & commands: the directory of all 139 features.
 *
 * Owner requirement (2026-10-22, Gemini Q2/Q8): Settings must include a
 * directory/search that indexes every feature with exactly five plain labels;
 * rows that are not switches must say so honestly, with an example phrase and
 * a screen path; never a fake switch.
 *
 * THE DATA IS NOT HAND-TYPED. `src/feature-directory.js` is generated by
 * `tools/gen_feature_directory.py` from the canonical, checked
 * `contract/feature-controls.json`; this suite checks the page against that
 * contract and fails if the generated copy is stale (source sha), if a feature
 * is missing, if a sixth label appears, or if a row lost its example/screen
 * path. It also proves the card is an INDEX: no button, toggle, checkbox or
 * select inside the list, and the only interactive thing is the filter.
 */
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import * as K from "./uikit.mjs";

const HERE = dirname(fileURLToPath(import.meta.url));
const read = (p) => readFileSync(join(HERE, "..", p));
const readJSON = (p) => JSON.parse(read(p).toString("utf8"));
const FIXTURE = readJSON("tests/fixtures/feature-directory.json");
const CONTRACT = readJSON("../contract/feature-controls.json");
// The five labels come from the contract itself: this suite checks that the
// page's copy carries exactly the contract's five, in the contract's order, and
// that the generated file's label_order is the same list (so the page cannot
// stamp its own wording on them).
const LABELS = Object.keys(CONTRACT.labels);

const { base, close } = await K.serve();
const browser = await K.launch();
const fails = [];
const check = async (name, fn) => {
  try {
    await fn();
    console.log(`ok    ${name}`);
  } catch (e) {
    fails.push(name);
    console.log(`FAIL  ${name}\n      ${e.message}`);
  }
};

const open = async () => {
  const page = await K.open(browser, base, "settings.html", {},
    { width: 1000, height: 2000 });
  await page.waitForFunction(
    () => document.querySelectorAll("#fd-list .fd-row").length > 0,
    { timeout: 10000 });
  return page;
};

const directory = (page) => page.evaluate(() => {
  const card = document.getElementById("fd-title")?.closest(".card");
  const rows = [...document.querySelectorAll("#fd-list .fd-row")];
  return {
    cardId: card ? (card.id || "(anonymous)") : null,
    count: rows.length,
    labels: [...new Set(rows.map((r) =>
      (r.querySelector(".fd-label") || {}).textContent || ""))].sort(),
    names: rows.map((r) => (r.querySelector(".fd-name") || {}).textContent || ""),
    missingExample: rows.filter((r) => !(r.querySelector(".fd-example") || {})
      .textContent).length,
    missingWhere: rows.filter((r) => !(r.querySelector(".fd-where") || {})
      .textContent).length,
    controls: document.querySelectorAll(
      "#fd-list button, #fd-list input, #fd-list select, #fd-list textarea, " +
      "#fd-list [role=switch], #fd-list [role=checkbox]").length,
  };
});

const countsOf = (rows) => {
  const counts = {};
  for (const row of rows) counts[row.label] = (counts[row.label] || 0) + 1;
  return counts;
};

await check("the generated copy matches the canonical contract", async () => {
  // A changed contract must force a regeneration: the page's copy carries the
  // contract's sha256, so this fails instead of quietly showing old labels.
  const sha = createHash("sha256").update(read("../contract/feature-controls.json"))
    .digest("hex");
  assert.equal(FIXTURE.source_sha256, sha,
    "feature-directory.js/fixture is stale - run python -B tools/gen_feature_directory.py");
  assert.equal(FIXTURE.feature_count, CONTRACT.feature_count);
  assert.equal(FIXTURE.feature_count, 139);
  assert.equal(CONTRACT.feature_count, 139);
  assert.equal(LABELS.length, 5, `the contract has ${LABELS.length} labels`);
  assert.deepEqual(FIXTURE.label_order, LABELS,
    "the generated order is not the contract's label order");
  assert.deepEqual(Object.keys(FIXTURE.labels), LABELS);
});

await check("the page renders all 139 features, grouped under exactly five labels", async () => {
  const page = await open();
  const d = await directory(page);
  assert.equal(d.count, 139, `the page shows ${d.count} rows`);
  assert.deepEqual(d.labels, [...LABELS].sort());
  assert.equal(d.missingExample, 0, "a row lost its example phrase");
  assert.equal(d.missingWhere, 0, "a row lost its screen path");
  // The counts come from the contract, never from the page's own wording.
  const expected = countsOf(CONTRACT.features);
  const shown = countsOf(FIXTURE.rows);
  assert.deepEqual(shown, expected,
    `label counts drifted: page ${JSON.stringify(shown)} contract ${JSON.stringify(expected)}`);
  assert.deepEqual([...new Set(FIXTURE.rows.map((r) => r.title))].sort(),
    [...new Set(CONTRACT.features.map((f) => f.name))].sort());
  await page.close();
});

await check("it is a directory, not a second settings surface", async () => {
  const page = await open();
  const d = await directory(page);
  assert.equal(d.controls, 0,
    `${d.controls} control(s) were drawn inside the directory - it must be words only`);
  // The one interactive thing is the filter, and it changes no setting.
  const filter = await page.evaluate(() => {
    const el = document.getElementById("fd-filter");
    return el ? { type: el.type, tag: el.tagName } : null;
  });
  assert.deepEqual(filter, { type: "search", tag: "INPUT" });
  await page.close();
});

await check("the filter narrows the list and clearing it restores every row", async () => {
  const page = await open();
  await page.locator("#fd-filter").fill("clipboard");
  await page.waitForTimeout(250);
  const shown = await directory(page);
  assert.ok(shown.count > 0 && shown.count < 139,
    `the filter showed ${shown.count} rows for "clipboard"`);
  const countText = await page.locator("#fd-count").textContent();
  assert.match(countText, new RegExp(`${shown.count} of 139`), countText);
  await page.locator("#fd-filter").fill("");
  await page.waitForTimeout(250);
  assert.equal((await directory(page)).count, 139);
  await page.close();
});

await check("the page names the screen the generated rows point at", async () => {
  const page = await open();
  const text = await page.evaluate(() =>
    (document.getElementById("fd-title")?.closest(".card") || {}).innerText || "");
  // The contract names the directory "Settings, All features and abilities"
  // (with a "(planned)" suffix until it is real); the visible card must carry
  // that name, so a row never points at a screen whose own text is missing.
  assert.match(text, /all features and abilities/i);
  // Users also know it as "Abilities & commands"; the card says both.
  assert.match(text, /Abilities & commands/);
  await page.close();
});

await check("Settings search finds the features inside the directory", async () => {
  const page = await open();
  const type = async (text) => {
    await page.locator("#settings-search-input").fill(text);
    await page.waitForTimeout(250);
  };
  const cardShown = () => page.evaluate(() => {
    const card = document.getElementById("fd-title")?.closest(".card");
    return Boolean(card) && !card.hidden;
  });
  for (const words of ["clipboard history", "retirement what-if",
    "morning briefing"]) {
    await type(words);
    assert.equal(await cardShown(), true,
      `"${words}" did not find the abilities directory`);
    await type("");
  }
  await page.close();
});

await check("the labels are the owner's five, never a sixth", async () => {
  for (const label of LABELS) {
    assert.equal(typeof FIXTURE.labels[label], "string",
      `${label} has no plain description`);
    assert.ok(FIXTURE.labels[label].trim().length > 0);
  }
  const bad = FIXTURE.rows.filter((r) => !LABELS.includes(r.label));
  assert.deepEqual(bad.map((r) => r.id), []);
  // Every row keeps the honest "not a control" reminder the page renders by
  // words only; a future edit that treats status as a toggle fails here.
  assert.ok(FIXTURE.rows.every((r) => r.not_a_control === true));
});

await browser.close();
close();
console.log(fails.length ? `\n${fails.length} failed: ${fails.join(", ")}`
  : "\nthe abilities directory indexes all 139 features honestly");
process.exit(fails.length ? 1 : 0);
